export function moneyParts(vehicle){const raw=String(vehicle.price||'').trim(),currency=['USD','BOB'].includes(vehicle.currency)?vehicle.currency:/USD|US\$|\$us|d[oó]lar/i.test(raw)?'USD':/\bBs\b|BOB|bolivian/i.test(raw)?'BOB':'';let amount=Number(vehicle.priceAmount);if(!Number.isFinite(amount)||amount<=0){let value=raw.replace(/[^\d.,]/g,'');if(/[.,]\d{2}$/.test(value))value=value.slice(0,-3).replace(/[.,]/g,'')+'.'+value.slice(-2);else value=value.replace(/[.,]/g,'');amount=Number(value);}return{amount:Number.isFinite(amount)&&amount>0?amount:null,currency};}
export function priceLabel(vehicle){const {amount,currency}=moneyParts(vehicle);if(!amount)return vehicle.price||'Precio a consultar';return(currency==='BOB'?'Bs ':currency==='USD'?'US$ ':'')+amount.toLocaleString('en-US',{maximumFractionDigits:2})+(currency?'':' · moneda por confirmar');}
export function normalizeMoney(input,out){const currency=['USD','BOB'].includes(input.currency)?input.currency:'';if(input.priceAmount!==undefined){if(input.priceAmount===null||input.priceAmount===''){out.priceAmount=null;out.currency=currency;out.price='A consultar';return;}const amount=Number(input.priceAmount);if(!Number.isFinite(amount)||amount<=0||amount>1000000000)throw Error('Introduce un precio válido mayor que cero.');if(!currency)throw Error('Selecciona la moneda (Bs o Dólares) para publicar el precio.');out.priceAmount=amount;out.currency=currency;out.price=priceLabel(out);return;}const old=moneyParts(input);out.currency=currency||old.currency;out.priceAmount=old.amount;}
